mapper.select:
select id as "id", member_id as "memberId", amount as "amount", balance_after as "balanceAfter",
       reason as "reason", ref_key as "refKey", place_id as "placeId", create_time as "createTime"
from city_coin_ledger where ref_key = #{refKey}

select id as "id", amount as "amount", balance_after as "balanceAfter", reason as "reason",
       place_id as "placeId", create_time as "createTime"
from city_coin_ledger where member_id = #{memberId}
order by id desc limit #{limit}
